        internal static BossRewardProfile[] CreateNyxRewards()
        {
            BossRewardAction Pull() => new BossRewardAction(BossRewardActionKind.NativeSpeed,count:BossNyxBalance.RewardPullCount,magnitudeMilli:BossNyxBalance.RewardPullMagnitudeMilli,speedMilli:BossNyxBalance.RewardPullSpeedMilli);
            BossRewardAction Radius() => new BossRewardAction(BossRewardActionKind.NativeState,rangeMilli:BossNyxBalance.RewardRadiusRangeMilli,order:1,magnitudeMilli:BossNyxBalance.RewardRadiusMagnitudeMilli);
            BossRewardAction End() => new BossRewardAction(BossRewardActionKind.NativeDamage,BossNyxBalance.RewardEndValueMilli,BossNyxBalance.RewardEndCapMilli,durationMillis:BossNyxBalance.RewardEndDurationMillis,count:BossNyxBalance.RewardEndCount,order:2,magnitudeMilli:BossNyxBalance.RewardEndMagnitudeMilli,rangeMilli:BossNyxBalance.RewardEndRangeMilli);
            return new[] { new BossRewardProfile(NyxRewardId,NyxSetId,"St_U_HerWorld",BossRewardAdapter.HerWorld,new[]
            {
                new BossRewardStage(1,new Txt("自身が装着している「彼女の世界（Her World）」の継続ダメージ領域内にいる通常の敵に、毎秒1mの追加の引き寄せ効果を付与する。1回の効果で敵1体に追加できる移動は2mまで。ボスと行動妨害が効かない敵は対象外で、元の挙動や持続時間は変わらない。", "Your equipped Her World pulls normal enemies inside its damage-over-time area an additional 1m per second, up to 2m of additional movement per enemy for each use. Does not affect bosses and enemies immune to crowd control. The skill's original behavior and duration are unchanged.", "自身装备的“她的世界（Her World）”对持续伤害区域内的普通敌人额外施加每秒1m的拉近效果，每次施放对每名敌人追加的移动距离最多2m。首领和免疫控制的敌人不受影响，原有行为和持续时间不变。"),new[] { Pull() }),
                new BossRewardStage(2,new Txt("固有報酬の段階1の効果に加え、「彼女の世界」の継続ダメージの半径が、上限8mまで最大1m広がる。持続が終わったとき、または装備を外したときは、増えた分だけが元に戻る。元の光属性の継続ダメージやダメージ量は変わらない。", "In addition to boss reward stage 1, increase Her World's damage-over-time radius by up to 1m, to a maximum of 8m. Only this increase is removed when the effect ends or you unequip it. Its original Light damage over time and damage amount are unchanged.", "除首领专属奖励阶段1的效果外，“她的世界”的持续伤害半径最多增加1m，上限8m。效果结束或卸下装备时，仅撤销增加的范围。原有光属性持续伤害和伤害量不变。"),new[] { Pull(),Radius() }),
                new BossRewardStage(3,new Txt("固有報酬の段階2の効果に加え、継続ダメージが命中した敵を最大3体まで記録する。この効果が自然に終わったとき、記録した敵への追撃が命中すると、それぞれ1回だけ攻撃力・魔力の高い方の45%の光属性ダメージを追加で与える。また、元のスタン時間が上限3秒まで最大0.25秒延びる。死亡による中断、強制解除、部屋移動のときは追加ダメージを与えない。", "In addition to boss reward stage 2, remember up to 3 enemies hit by Her World's damage over time. When the effect ends naturally, its follow-up hit deals additional Light damage equal to 45% of whichever is higher: your Attack or Ability Power, once to each remembered enemy it hits. Also extend the original stun by up to 0.25 seconds, to a maximum of 3 seconds. No additional damage is dealt if the effect is interrupted by death, forcibly removed, or ended by changing rooms.", "除首领专属奖励阶段2的效果外，记录被持续伤害命中的最多3名敌人。效果自然结束时，后续追击命中被记录的敌人后，各额外造成1次相当于攻击力与法术强度中较高一方45%的光属性伤害。此外原有眩晕时间最多延长0.25秒，上限3秒。因死亡中断、被强制解除或切换房间时，不造成追加伤害。"),new[] { Pull(),Radius(),End() }),
            }) };
        }
